package app

import (
	"testing"

	"git.kebcloud.no/keb/lazysecrets/internal/ui/panes"
)

func TestChangelogFields(t *testing.T) {
	t.Parallel()
	md := "# Changelog\n\nEvery release of lazysecrets, newest first.\n\n## v0.2.0 – 2026-10-12\n\n### Added\n\n" +
		"- Search ([#11](https://x/pulls/11)) ([65dc2d7](https://x/commit/65dc2d7))\n\n### Fixed\n\n- A fix (#3)\n\n" +
		"## v0.1.0 – 2026-10-10\n\nHello world 👋\n\n<!-- generated by git-cliff (cliff.toml) -->\n"
	got := changelogFields(md)
	want := []panes.Field{
		{Label: "v0.2.0", Value: "2026-10-12", Info: true},
		{Value: "added: Search (#11) (65dc2d7)"},
		{Value: "fixed: A fix (#3)"},
		{Label: "v0.1.0", Value: "2026-10-10", Info: true},
		{Value: "Hello world 👋"},
	}
	if len(got) != len(want) {
		t.Fatalf("got %+v", got)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Errorf("row %d: %+v, want %+v", i, got[i], want[i])
		}
	}
}
